-- IP1 Stage A (implementation plan IP1, 2026-09-27): complete the AI relationship catalog, and register
-- check_data_feasibility (Research Plan feasibility) in Tool_Catalog.
--
-- Eleven relationships the DataNeed flow could not express (C05: a sector scope could not restrict broker flows):
--   sector/industry filter  IDX_Stock_Universe -> IDX_Broker_Summary, Feature 01, Feature 02, Feature 03  CURRENT_STATE
--   broker profile          IDX_Broker_Profile -> Feature 02                                      CURRENT_STATE
--   price + broker          Price_Stock_Indonesia_IDX -> IDX_Broker_Summary, Feature 02, Feature 03  EXACT_DATE
--   features + broker       Feature_01_Stock_Daily -> IDX_Broker_Summary, Feature 02, Feature 03     EXACT_DATE
-- Each has one entity key besides the date, so the single-key DataNeed contract can use it today (the composite keys of
-- Broker Summary <-> Feature 02 and Feature 02 <-> Feature 03 wait for IP1 Stage B). The "one" side is unique on the
-- key (primary keys: IDX_Stock_Universe Ticker, IDX_Broker_Profile broker_code, Price and Feature 01 ticker+date).
-- None needs preaggregation for its declared grain, which is always the "many" side: the one-side values repeat per
-- row, and each description says what to aggregate before a coarser result. As a semi-join restriction (the Governor's
-- INNER pushdown) a relationship never multiplies rows. All CURRENT_STATE joins use today's classification: the
-- validator's HISTORICAL_REFERENCE_USES_CURRENT_STATE warning applies (point-in-time history is IP1 Stage D).
--
-- Alignment with Feature_Relationship_Catalog (verified below): the two new pairs between Feature tables (Feature 01 ->
-- Feature 02, Feature 01 -> Feature 03) have active Feature rows with the same key columns, whose safe grain allows the
-- many-side grain without aggregation; their requires_preaggregation=true there describes a ticker-date result, which
-- these AI rows do not claim. Feature 02 -> Feature 03 stays requires_preaggregation=true in both catalogs.
--
-- Rollback (forward-only: write a new migration): set is_allowed=false on these rows (DataNeed then refuses them with
-- RELATIONSHIP_NOT_ALLOWED) and delete the Tool_Catalog row; no table, column or market-data row is touched.
BEGIN;

SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF (SELECT count(*) FROM public."AI_table_catalog"
        WHERE table_name IN ('IDX_Stock_Universe', 'IDX_Broker_Profile', 'IDX_Broker_Summary', 'Price_Stock_Indonesia_IDX',
                             'Feature_01_Stock_Daily', 'Feature_02_Broker_Rolling', 'Feature_03_Stock_Broker_Daily')) <> 7 THEN
        RAISE EXCEPTION 'The seven tables are not all in AI_table_catalog';
    END IF;
    IF EXISTS (SELECT 1 FROM public."AI_catalog_relationships" WHERE (left_table, right_table) IN (('IDX_Stock_Universe','IDX_Broker_Summary'),('IDX_Stock_Universe','Feature_01_Stock_Daily'),('IDX_Stock_Universe','Feature_02_Broker_Rolling'),('IDX_Stock_Universe','Feature_03_Stock_Broker_Daily'),('IDX_Broker_Profile','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','IDX_Broker_Summary'),('Price_Stock_Indonesia_IDX','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','Feature_03_Stock_Broker_Daily'),('Feature_01_Stock_Daily','IDX_Broker_Summary'),('Feature_01_Stock_Daily','Feature_02_Broker_Rolling'),('Feature_01_Stock_Daily','Feature_03_Stock_Broker_Daily'))
                  OR (right_table, left_table) IN (('IDX_Stock_Universe','IDX_Broker_Summary'),('IDX_Stock_Universe','Feature_01_Stock_Daily'),('IDX_Stock_Universe','Feature_02_Broker_Rolling'),('IDX_Stock_Universe','Feature_03_Stock_Broker_Daily'),('IDX_Broker_Profile','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','IDX_Broker_Summary'),('Price_Stock_Indonesia_IDX','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','Feature_03_Stock_Broker_Daily'),('Feature_01_Stock_Daily','IDX_Broker_Summary'),('Feature_01_Stock_Daily','Feature_02_Broker_Rolling'),('Feature_01_Stock_Daily','Feature_03_Stock_Broker_Daily'))) THEN
        RAISE EXCEPTION 'One of the new relationships (or its reverse) already exists';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_data_feasibility') THEN
        RAISE EXCEPTION 'check_data_feasibility is already registered';
    END IF;
    -- the key columns exist in the physical tables
    IF (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND (table_name, column_name) IN (
            ('IDX_Stock_Universe', 'Ticker'), ('IDX_Broker_Profile', 'broker_code'), ('IDX_Broker_Summary', 'Symbol'),
            ('IDX_Broker_Summary', 'Date'), ('Price_Stock_Indonesia_IDX', 'ticker'), ('Price_Stock_Indonesia_IDX', 'date'),
            ('Feature_01_Stock_Daily', 'ticker'), ('Feature_01_Stock_Daily', 'date'), ('Feature_02_Broker_Rolling', 'ticker'),
            ('Feature_02_Broker_Rolling', 'date'), ('Feature_02_Broker_Rolling', 'broker'),
            ('Feature_03_Stock_Broker_Daily', 'ticker'), ('Feature_03_Stock_Broker_Daily', 'date'))) <> 13 THEN
        RAISE EXCEPTION 'A relationship key column is missing';
    END IF;
END
$preflight$;

INSERT INTO public."AI_catalog_relationships" (
    left_table, left_columns, right_table, right_columns, relationship_type, temporal_rule, safe_output_grain,
    requires_preaggregation, description, version, is_allowed, supported_join_semantics, left_time_column,
    right_time_column
)
VALUES
    ('IDX_Stock_Universe', ARRAY['Ticker'], 'IDX_Broker_Summary', ARRAY['Symbol'], 'ONE_TO_MANY', 'Current-state reference metadata',
     'Broker Summary primary-key grain (Date x Symbol x Broker x Investor Type x Market Board)', false,
     'Current stock-universe identity and classification (Sector, Industry) joined to broker activity. Restricts broker rows to the tickers of a sector or industry without a typed ticker list. Symbols outside the universe (rights, warrants) have no match. Classification is current state, not point in time.',
     'v1', true, ARRAY['CURRENT_STATE'], NULL, NULL),
    ('IDX_Stock_Universe', ARRAY['Ticker'], 'Feature_01_Stock_Daily', ARRAY['ticker'], 'ONE_TO_MANY', 'Current-state reference metadata',
     'date x ticker', false,
     'Current stock-universe identity and classification joined to daily stock features. Feature 01 already carries current sector and industry; this relationship lets a universe scope (for example Is Common Stock or Industry) restrict it. Current state, not point in time.',
     'v1', true, ARRAY['CURRENT_STATE'], NULL, NULL),
    ('IDX_Stock_Universe', ARRAY['Ticker'], 'Feature_02_Broker_Rolling', ARRAY['ticker'], 'ONE_TO_MANY', 'Current-state reference metadata',
     'date x ticker x broker x investor_type x market_board', false,
     'Current stock-universe classification joined to broker rolling flows, so a sector or industry scope restricts Feature 02 by ticker (for example mining: Industry Metals & Minerals or Coal). Boards and investor types stay separate rows. Current state, not point in time.',
     'v1', true, ARRAY['CURRENT_STATE'], NULL, NULL),
    ('IDX_Stock_Universe', ARRAY['Ticker'], 'Feature_03_Stock_Broker_Daily', ARRAY['ticker'], 'ONE_TO_MANY', 'Current-state reference metadata',
     'date x ticker x market_board', false,
     'Current stock-universe classification joined to stock-level daily broker features; boards stay separate rows. Current state, not point in time.',
     'v1', true, ARRAY['CURRENT_STATE'], NULL, NULL),
    ('IDX_Broker_Profile', ARRAY['broker_code'], 'Feature_02_Broker_Rolling', ARRAY['broker'], 'ONE_TO_MANY', 'Current-state broker metadata',
     'date x ticker x broker x investor_type x market_board', false,
     'Current broker identity, domestic/foreign broker type and usage classification joined to broker rolling flows (restrict to brokers of a type or classification). broker_type is broker domicile; investor_type in Feature 02 is the source investor. Current state, not point in time.',
     'v1', true, ARRAY['CURRENT_STATE'], NULL, NULL),
    ('Price_Stock_Indonesia_IDX', ARRAY['ticker','date'], 'IDX_Broker_Summary', ARRAY['Symbol','Date'], 'ONE_TO_MANY', 'Exact trading date',
     'Broker Summary primary-key grain; price values repeat on every broker row of the ticker and date', false,
     'Price candle of the same ticker and trading date joined to broker activity. Joined rows keep the broker grain (the price repeats per broker, investor type and board); aggregate broker rows to ticker and date before a ticker-date result. A missing candle is never replaced by an earlier one.',
     'v1', true, ARRAY['EXACT_DATE'], 'date', 'Date'),
    ('Price_Stock_Indonesia_IDX', ARRAY['ticker','date'], 'Feature_02_Broker_Rolling', ARRAY['ticker','date'], 'ONE_TO_MANY', 'Exact trading date',
     'date x ticker x broker x investor_type x market_board; price values repeat per row', false,
     'Price candle of the same ticker and trading date joined to broker rolling flows at the Feature 02 grain (price repeats per broker, investor type and board); aggregate Feature 02 to ticker and date before a ticker-date result.',
     'v1', true, ARRAY['EXACT_DATE'], 'date', 'date'),
    ('Price_Stock_Indonesia_IDX', ARRAY['ticker','date'], 'Feature_03_Stock_Broker_Daily', ARRAY['ticker','date'], 'ONE_TO_MANY', 'Exact trading date',
     'date x ticker x market_board; price values repeat per board', false,
     'Price candle of the same ticker and trading date joined to stock-level broker features at the Feature 03 grain (one row per board); filter a board, normally Regular, before a ticker-date result.',
     'v1', true, ARRAY['EXACT_DATE'], 'date', 'date'),
    ('Feature_01_Stock_Daily', ARRAY['ticker','date'], 'IDX_Broker_Summary', ARRAY['Symbol','Date'], 'ONE_TO_MANY', 'Exact trading date',
     'Broker Summary primary-key grain; Feature 01 values repeat on every broker row', false,
     'Daily stock features (returns, indicators) of the same ticker and date joined to broker activity at the broker grain; aggregate broker rows to ticker and date before a ticker-date result.',
     'v1', true, ARRAY['EXACT_DATE'], 'date', 'Date'),
    ('Feature_01_Stock_Daily', ARRAY['ticker','date'], 'Feature_02_Broker_Rolling', ARRAY['ticker','date'], 'ONE_TO_MANY', 'Exact trading date',
     'date x ticker x broker x investor_type x market_board; Feature 01 values repeat per row', false,
     'Daily stock features joined to broker rolling flows at the Feature 02 grain, as Feature_Relationship_Catalog allows without aggregation; aggregate Feature 02 to ticker and date (sum investor types per broker first) before a ticker-date result.',
     'v1', true, ARRAY['EXACT_DATE'], 'date', 'date'),
    ('Feature_01_Stock_Daily', ARRAY['ticker','date'], 'Feature_03_Stock_Broker_Daily', ARRAY['ticker','date'], 'ONE_TO_MANY', 'Exact trading date',
     'date x ticker x market_board; Feature 01 values repeat per board', false,
     'Daily stock features joined to stock-level broker features at the Feature 03 grain, as Feature_Relationship_Catalog allows; filter a board, normally Regular, or preaggregate Feature 03 before a ticker-date result.',
     'v1', true, ARRAY['EXACT_DATE'], 'date', 'date');

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
