e catalog.","enum":["CURRENT_STATE","EXACT_DATE","AS_OF","EFFECTIVE_DATED"],"type":"string"},"join_type":{"description":"INNER restricts the left request to rows with a match in the right request''s scope; LEFT leaves it unrestricted. Each request is delivered as its own dataset; the analysis joins them.","enum":["INNER","LEFT"],"type":"string"},"left_column":{"type":"string"},"left_request_id":{"type":"string"},"left_time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EXACT_DATE / AS_OF: the catalog left time column; else null."},"relationship_id":{"description":"Catalog relationship_id between the two requests'' tables.","type":"integer"},"right_column":{"type":"string"},"right_request_id":{"type":"string"},"right_time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EXACT_DATE / AS_OF: the catalog right time column; else null."}},"required":["relationship_id","left_request_id","left_column","right_request_id","right_column","join_type","join_semantics","left_time_column","right_time_column","as_of_direction","effective_from_column","effective_to_column"],"type":"object"},"type":"array"},"request_group_id":{"description":"Lower-case id of this data need, e.g. data_request_1; revisions keep it.","type":"string"},"revision":{"description":"1 for the first submission, then the next number for each revision.","type":"integer"},"spec_version":{"enum":["data_need_spec/v1"],"type":"string"},"subject":{"additionalProperties":false,"properties":{"asset_type":{"anyOf":[{"type":"string"},{"type":"null"}]},"data_domain":{"type":"string"},"entity_type":{"type":"string"}},"required":["data_domain","entity_type","asset_type"],"type":"object"}},"required":["spec_version","request_group_id","revision","mode","question","subject","data_requests","relationships"],"type":"object"}'::jsonb,
     '{"description":"FEASIBLE with draft_id and, per data request, estimated rows, extraction parts and the Governor status; NOT_FEASIBLE naming the refused request; or REVISION_REQUIRED / CATALOG_UNAVAILABLE with the validator''s issues.","properties":{"draft_id":{},"error":{},"issues":{},"next_action":{},"requests":{},"status":{},"warnings":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 285, 40000, 200, 40000, NULL,
     false, false, false, '{"draft_retention_days":7,"executor_service":"market-python-sandbox","feature_flag":"AI_ENABLE_PLAN_FEASIBILITY","governor_endpoint":"POST /v1/extract with estimate_only (no rows read)","handler":"app/tools/data_planner.py (check_feasibility, ExecutionPlanner.estimate)","max_parts_per_request":64,"never":["extraction","revision consumption","Research Governor review"],"offered_in_turns":["PROPOSE","REVISE","REPLAN"],"registry_state":"Registered in market-ai-orc only with AI_ENABLE_PLAN_FEASIBILITY, Research Plan confirmation, the DataNeed flow and the sandbox capability; is_active=false like the other DataNeed tools (market-ai-backend never lists it).","runtime_commit":"fd23d12","runtime_service":"market-ai-orc","sandbox_capability":"GET /v1/runtime plan_feasibility version 1","sandbox_endpoints":["POST /v1/data-needs/check","GET /v1/data-need-drafts/{draft_id}"],"statuses":["FEASIBLE","NOT_FEASIBLE","REVISION_REQUIRED","CATALOG_UNAVAILABLE"]}'::jsonb, 'v1', false);

DO $verify$
DECLARE
    unique_one integer;
BEGIN
    IF (SELECT count(*) FROM public."AI_catalog_relationships"
        WHERE (left_table, right_table) IN (('IDX_Stock_Universe','IDX_Broker_Summary'),('IDX_Stock_Universe','Feature_01_Stock_Daily'),('IDX_Stock_Universe','Feature_02_Broker_Rolling'),('IDX_Stock_Universe','Feature_03_Stock_Broker_Daily'),('IDX_Broker_Profile','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','IDX_Broker_Summary'),('Price_Stock_Indonesia_IDX','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','Feature_03_Stock_Broker_Daily'),('Feature_01_Stock_Daily','IDX_Broker_Summary'),('Feature_01_Stock_Daily','Feature_02_Broker_Rolling'),('Feature_01_Stock_Daily','Feature_03_Stock_Broker_Daily')) AND is_allowed AND NOT requires_preaggregation
          AND cardinality(supported_join_semantics) = 1) <> 11 THEN
        RAISE EXCEPTION 'The eleven relationships are not all registered';
    END IF;
    -- every EXACT_DATE row names its time columns inside its key; every row leaves exactly one entity key pair
    IF EXISTS (SELECT 1 FROM public."AI_catalog_relationships"
               WHERE (left_table, right_table) IN (('IDX_Stock_Universe','IDX_Broker_Summary'),('IDX_Stock_Universe','Feature_01_Stock_Daily'),('IDX_Stock_Universe','Feature_02_Broker_Rolling'),('IDX_Stock_Universe','Feature_03_Stock_Broker_Daily'),('IDX_Broker_Profile','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','IDX_Broker_Summary'),('Price_Stock_Indonesia_IDX','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','Feature_03_Stock_Broker_Daily'),('Feature_01_Stock_Daily','IDX_Broker_Summary'),('Feature_01_Stock_Daily','Feature_02_Broker_Rolling'),('Feature_01_Stock_Daily','Feature_03_Stock_Broker_Daily'))
                 AND ((cardinality(left_columns) - CASE WHEN 'EXACT_DATE' = ANY(supported_join_semantics) THEN 1 ELSE 0 END) <> 1
                      OR ('EXACT_DATE' = ANY(supported_join_semantics)
                          AND (NOT left_time_column = ANY(left_columns) OR NOT right_time_column = ANY(right_columns))))) THEN
        RAISE EXCEPTION 'A relationship does not reduce to one entity key pair';
    END IF;
    -- Feature-to-Feature pairs agree with an active Feature_Relationship_Catalog row on the key columns
    IF EXISTS (SELECT 1 FROM public."AI_catalog_relationships" AS ai
               WHERE (ai.left_table, ai.right_table) IN (('IDX_Stock_Universe','IDX_Broker_Summary'),('IDX_Stock_Universe','Feature_01_Stock_Daily'),('IDX_Stock_Universe','Feature_02_Broker_Rolling'),('IDX_Stock_Universe','Feature_03_Stock_Broker_Daily'),('IDX_Broker_Profile','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','IDX_Broker_Summary'),('Price_Stock_Indonesia_IDX','Feature_02_Broker_Rolling'),('Price_Stock_Indonesia_IDX','Feature_03_Stock_Broker_Daily'),('Feature_01_Stock_Daily','IDX_Broker_Summary'),('Feature_01_Stock_Daily','Feature_02_Broker_Rolling'),('Feature_01_Stock_Daily','Feature_03_Stock_Broker_Daily'))
                 AND ai.left_table LIKE 'Feature\_%' AND ai.right_table LIKE 'Feature\_%'
                 AND NOT EXISTS (SELECT 1 FROM public."Feature_Relationship_Catalog" AS f
                                 WHERE f.is_active AND f.left_feature_table = ai.left_table
                                   AND f.right_feature_table = ai.right_table
                                   AND f.left_join_columns = ai.left_columns
                                   AND f.right_join_columns = ai.right_columns)) THEN
        RAISE EXCEPTION 'A Feature pair has no matching active Feature_Relationship_Catalog row';
    END IF;
    -- the "one" sides are unique on their keys (primary keys)
    SELECT count(*) INTO unique_one FROM pg_index AS i JOIN pg_class AS c ON c.oid = i.indrelid
    WHERE i.indisprimary AND c.relname IN ('IDX_Stock_Universe', 'IDX_Broker_Profile', 'Price_Stock_Indonesia_IDX',
                                           'Feature_01_Stock_Daily');
    IF unique_one <> 4 THEN
        RAISE EXCEPTION 'A one-side table has no primary key';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_data_feasibility' AND version = 'v1'
                   AND NOT is_active AND tool_specific_limits->>'runtime_commit' = 'fd23d12') THEN
        RAISE EXCEPTION 'check_data_feasibility was not registered';
    END IF;
END
$verify$;

COMMIT;
